INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Hint`, `Sources`) VALUES
(474200, 0, 4742, 0, 0, 15, 'Hrothgar''s Landing', 'Hrothgar''s Landing is a small island in the North Sea, across the strait from the Argent Tournament grounds, shrouded in mist. It was a tuskarr settlement until the Kvaldir came, seafaring vrykul raiders who sail out of the fog: they slew the villagers, left them lying where they fell and renamed the island for their leader, Drottinn Hrothgar. Cargo they have stolen lies scattered across it, and the tournament fears its own grounds will be next.', '', 'quest 14074 description (island to the north, seen shrouded in mist from the grounds; ship''s cargo taken there); quest 14080 description (Kvaldir murdered the tuskarr inhabitants and renamed the island Hrothgar''s Landing; the tournament their next target); quest 14101 description (kvaldir are seafaring vrykul; their leader the veteran raider Drottinn Hrothgar; circle of tuskarr statues in the northeast); quest 14104 description (Ornolf''s ship at anchor at the eastern end of the island''s harbor); spell_area: spell 68085 Mist of the Kvaldir (screen effect) on 4742 and 4760 for everyone, no quest (wowhead spell 68085); zone_areas 4742: Kvaldir Reaver 34838, Kvaldir Mist Binder 34839, Slain Tualiq Villager 34852, Stolen Tallstrider Leg 195274; gameobjects 195328 Tualiq Monuments (10404,939) and 195330 Deck of the Bor''s Fury (10004,645), posarea 4742; borean.json 353707 and 353721 (the tuskarr call the Kvaldir walkers of the fog); warcraft.wiki.gg/wiki/Kvaldir (tuk-hariq); warcraft.wiki.gg/wiki/Hrothgar''s_Landing (island north of Icecrown across the Sea Reaver''s Run; tuskarr village conquered and renamed); quest 14101 description; creature_template 34980 subname The Sea Reaver; gameobject 195328 Tualiq Monuments (spell focus for the horn), posarea 4742; warcraft.wiki.gg/wiki/Drottinn_Hrothgar (kvaldir, The Sea Reaver, took the island from the tuskarr; added 3.2.0); warcraft.wiki.gg/wiki/Drottinn_Hrothgar (kvaldir raider who claimed Hrothgar''s Landing from the local tuskarr); quest 24442 description and objectives; item 49676 Kvaldir Attack Plans (starts 24442), dropped by Kvaldir Reaver 34838 and Kvaldir Mist Binder 34839 (5 percent); gameobject 201367 Heart of the Mists at the cave (10186,1182, posarea 4742), loot item 49678; creature_template 33817 subname Seneschal of the Argent Tournament; warcraft.wiki.gg/wiki/Kvaldir (Kvaldir Attack Plans added in patch 3.2.2, never followed up)'),
(474201, 1, 4742, 0, 0, 15, 'The Sea Reaver''s Run', 'The Sea Reaver''s Run is the strait between Hrothgar''s Landing and the tournament grounds, and the Kvaldir mist hangs over it as thickly as over the island. Two ships the elven orders sent north lie locked in battle there, the Sunreavers'' Firehawk and the Silver Covenant''s Wavecrest, boarded by Kvaldir raiders, and between them deepcallers aboard a raiding vessel call up the kraken that lives beneath the North Sea.', '', 'zone_areas 4760: Captain Aerthas Firehawk 35090, Firehawk Mariner 35070 and dead mariners 35079/35083, Captain Elleane Wavecrest 35102, Wavecrest Mariner 35098 and dead mariners 35104/35105, Kvaldir Berserker 34947, Kvaldir Harpooner 34907 and their dead 35080/35084, Kvaldir Deepcaller 35092, North Sea Kraken 34925 (all phase 1); quest 14136 description (the Firehawk on the western side of the Sea Reaver''s Run, between the island and the grounds); quest 14152 description (the Wavecrest on the east side of the pass); quest 14108 description (ships detained by a Kvaldir raiding vessel; the kraken beneath the North Sea); spell_area 68085 Mist of the Kvaldir on 4760; warcraft.wiki.gg/wiki/Captain_Aerthas_Firehawk (blood elf, Sunreavers); warcraft.wiki.gg/wiki/Captain_Elleane_Wavecrest (high elf, Silver Covenant); only their Wrath-era pages used; warcraft.wiki.gg/wiki/Kvaldir_Deepcaller (on the kvaldir raiding vessel in the middle of Sea Reaver''s Run); quest 14136 description (Girana: the Firehawk under attack, vastly outnumbered); quest 14152 description (Narasi: the Wavecrest intercepted by a raiding party headed for the grounds, slowly being taken); quest 14108 description (both orders sent ships north to engage the Kvaldir); quest 14108 description and objectives; zone_areas 4760: North Sea Kraken 34925, Kvaldir Deepcaller 35092; smart_scripts 34925 (flaming spear hits; dies at low health with Kraken Tooth Explosion)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(474200, 1, 0, 255, 'Orders carried by the raiders show they look far beyond Northrend: a map of the Eastern Kingdoms and Kalimdor marks the settlements their captains mean to raid.', 'quest 14074 description (island to the north, seen shrouded in mist from the grounds; ship''s cargo taken there)'),
(474200, 2, 0, 255, 'Drottinn Hrothgar, king of the seas as he called himself, was drawn out by a captured war horn and cut down in the circle of old tuskarr statues.', 'quest 14074 description (island to the north, seen shrouded in mist from the grounds; ship''s cargo taken there)');
